cd /tmp && cat > StackAllocNint.cs << 'EOF'
using System;

class Program
{
    static void Main()
    {
        Span<nint> nativeInts = stackalloc nint[5];
        for (int i = 0; i < nativeInts.Length; i++)
            nativeInts[i] = i * 10;

        for (int i = 0; i < nativeInts.Length; i++)
            Console.WriteLine($"nativeInts[{i}] = {nativeInts[i]}");

        Span<nuint> nativeUInts = stackalloc nuint[3];
        nativeUInts[0] = 42;
        Console.WriteLine($"\nnuint span element size: {sizeof(nuint)} bytes");
        Console.WriteLine($"nuint value: {nativeUInts[0]}");
    }
}
EOF
